from lib import *
S = SS('f139')
R = J('f139'); rw = R['raw']; gt = R['gt']; asg = R['asgi']; a2 = R['a2']
kr = list(rw); kg = list(gt)
steps = [
    step(f"纯 ASGI 应用(没有框架)跑在 uvicorn 单进程上,一个 2 秒的慢请求进行中,另一个什么都不做的请求要等多久:慢请求在协程里调用 time.sleep(2),另一个请求用了 {rw[kr[0]]:.0f} ms(整个事件循环被卡住了);改成 await asyncio.sleep(2),另一个请求只用 {rw[kr[1]]:.0f} ms;改成 await asyncio.to_thread(time.sleep, 2),{rw[kr[2]]:.0f} ms。事件循环是单线程的,协程里的阻塞调用会让所有请求一起停下。", b=bars([['time.sleep(阻塞)', rw[kr[0]], f'{rw[kr[0]]:.0f} ms'], ['await sleep', max(rw[kr[1]], 1), f'{rw[kr[1]]:.0f} ms'], ['to_thread', max(rw[kr[2]], 1), f'{rw[kr[2]]:.0f} ms']], rw[kr[0]], mark=[0], done=[1, 2]), t=tl(S(1)), mark=lidx(S(1), 'time.sleep(2)(阻塞)'), done=lidx(S(1), 'await asyncio.sleep(2)', 'to_thread'), kv=KV([['协程里阻塞', f'其它请求被卡 {rw[kr[0]]:.0f} ms'], ['await / to_thread', '不影响其它请求']], ['协程里阻塞'])),
    step(f"Flask 的 async 视图在 gunicorn gthread(8 线程)下:视图里 time.sleep(2)、await asyncio.sleep(2)、sync 视图里 time.sleep(2),另一个 /fast 请求都只要 {gt[kg[0]]:.0f}、{gt[kg[1]]:.0f}、{gt[kg[2]]:.0f} ms——每个请求在自己的线程里,互不影响。阻塞只占着自己的线程,所以在 WSGI 下 async 视图里调阻塞代码不会拖垮别的请求(第 137 篇)。", t=tl(S(2)), done=lidx(S(2), 'async 视图里', 'sync 视图里'), kv=KV([['gunicorn gthread', '每个请求一个线程,阻塞只影响自己']], ['gunicorn gthread'])),
    step(f"同一个 Flask 应用用 asgiref 的 WsgiToAsgi 放到 uvicorn 单进程上:不管是 async 视图里的 time.sleep(2)、async 视图里的 await asyncio.sleep(2),还是 sync 视图里的 time.sleep(2),另一个 /fast 请求都用了约 {asg[kg[0]]:.0f} ms——三种情况全部串行。原因我查了源码:WsgiToAsgi 里运行 WSGI 应用的方法被 @sync_to_async(默认 thread_sensitive=True)装饰,所有请求排到同一个线程里执行,一个慢请求就挡住后面的。", b=bars([['WsgiToAsgi', asg[kg[0]], f'{asg[kg[0]]:.0f} ms'], ['gunicorn gthread', max(gt[kg[0]], 1), f'{gt[kg[0]]:.0f} ms']], asg[kg[0]], mark=[0], done=[1]), t=tl(S(3)), mark=lidx(S(3), 'async 视图里', 'sync 视图里'), kv=KV([['WsgiToAsgi(默认)', '所有请求串行,慢请求挡住快请求'], ['原因', 'sync_to_async thread_sensitive=True']], ['WsgiToAsgi(默认)'])),
    step(f"换成 a2wsgi 的 WSGIMiddleware(同样在 uvicorn 单进程上):三种情况下另一个请求都只用 {a2[kg[0]]:.0f}、{a2[kg[1]]:.0f}、{a2[kg[2]]:.0f} ms——a2wsgi 把 WSGI 应用放到线程池里并发执行。把 WSGI 应用接到 ASGI 服务器上时,适配器的线程模型决定了会不会串行,要实测。", t=tl(S(4)), done=lidx(S(4), 'async 视图里', 'sync 视图里'), kv=KV([['a2wsgi', '线程池并发,不串行']], ['a2wsgi'])),
    step("在事件循环里「看得见」阻塞:asyncio.run(main(), debug=True) 并把 slow_callback_duration 设成 0.1 秒,协程里 time.sleep(0.5) 之后日志会打印「Executing <Task ...> took 0.501 seconds」——开发时打开 asyncio 的 debug 模式就能发现协程里的阻塞调用。", t=tl(S(5)), done=lidx(S(5), 'Executing'), kv=KV([['asyncio debug', '慢回调警告能暴露阻塞调用']], ['asyncio debug'])),
]
A = mkartf('f139', 139, 'Flask,asyncio,阻塞,ASGI,uvicorn,真实验证,动画演示',
    f'实测同步代码阻塞异步请求:uvicorn 上的纯 ASGI 应用里 time.sleep 让另一个请求等 {rw[kr[0]]:.0f} ms 而 await 与 to_thread 只要几 ms;gunicorn gthread 下互不影响;同一个 Flask 应用经 asgiref 的 WsgiToAsgi 放到 uvicorn 上全部串行({asg[kg[0]]:.0f} ms),换 a2wsgi 就不串行;asyncio debug 模式能暴露阻塞调用。',
    '协程里调用了一个阻塞函数会怎样?Flask 放到 ASGI 服务器上,sync 视图会不会拖慢整个服务?这篇用真实的 uvicorn、gunicorn 与两个 WSGI 到 ASGI 的适配器,把阻塞的影响范围量出来(还有一个我没预料到的串行结果)。',
    [(f'{rw[kr[0]]:.0f} ms', '协程里 time.sleep(2) 时,uvicorn 上另一个请求被卡的时间'), (f'{asg[kg[0]]:.0f} ms', 'WsgiToAsgi 下任意慢请求进行中,另一个快请求的耗时(全部串行)'), ('thread_sensitive=True', 'asgiref 的 sync_to_async 默认值,所有请求排到同一个线程')],
    [('协程里阻塞', '<p>上一篇:<a href="flask-async-view-boundary.html">Async View 的执行边界</a>;下一篇:<a href="flask-flask-and-asgi.html">Flask 与 ASGI</a>。</p>'), ('gunicorn gthread 下', None), ('WsgiToAsgi', '<p>这是本篇最出乎意料的结果:我原以为 sync 视图会被放进线程池并发执行,实测却是串行,所以去看了 asgiref 的源码确认原因。</p>'), ('a2wsgi', None), ('发现阻塞', None)],
    steps, [ENV_F + '。uvicorn 0.54.0、asgiref 3.12.1、a2wsgi 1.10.10、gunicorn gthread', '没有验证:hypercorn 等其它 ASGI 服务器、uvicorn 多 worker 下的行为、WsgiToAsgi 通过环境变量调整线程模型的可能、uvicorn 的 --limit-concurrency、a2wsgi 的线程池大小限制'], '同步代码阻塞异步请求')
